// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    Wallet c;
    function setUp() public { c = new Wallet(); }
    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0);
        vm.assume(amount <= type(uint256).max / 2);

        address user = makeAddr("user");
        vm.deal(user, amount);
        vm.prank(user);
        c.deposit{value: amount}();

        uint256 contractBalanceBefore = address(c).balance;
        vm.prank(user);
        c.withdraw(amount);
        uint256 contractBalanceAfter = address(c).balance;

        assertTrue(contractBalanceAfter == contractBalanceBefore - amount);
    }
}
